package com.ewu.matching.controller;
import com.ewu.matching.dto.response.NotificationResponse;import com.ewu.matching.service.NotificationService;import io.swagger.v3.oas.annotations.tags.Tag;import lombok.RequiredArgsConstructor;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@Tag(name="Notifications") @RestController @RequestMapping("/api/notifications") @RequiredArgsConstructor @PreAuthorize("isAuthenticated()")
public class NotificationController {private final NotificationService service;@GetMapping public ResponseEntity<List<NotificationResponse>> mine(){return ResponseEntity.ok(service.mine());}@GetMapping("/unread-count") public ResponseEntity<Map<String,Long>> count(){return ResponseEntity.ok(Map.of("count",service.unreadCount()));}@PutMapping("/{id}/read") public ResponseEntity<Void> read(@PathVariable Long id){service.markRead(id);return ResponseEntity.noContent().build();}@PutMapping("/read-all") public ResponseEntity<Void> all(){service.markAllRead();return ResponseEntity.noContent().build();}}
